export type ReviewedOnboardingLocale = {
  onboarding: Record<OnboardingStepId, OnboardingLocalizedCopy>;
  onboardingUi: OnboardingUiCopy;
  factoryFirstRun: ReviewedFactoryGuideCopy;
};

export const REVIEWED_ONBOARDING_LOCALES = Object.fromEntries(
  Object.entries(packs).map(([language, pack]) => [
    language,
    {
      onboarding: Object.fromEntries(
        ONBOARDING_STEP_IDS.map((step) => [
          step,
          {
            chapter: pack.chapters[CHAPTER_BY_STEP[step]],
            label: pack.labels[step] ?? ONBOARDING_EN_COPY[step].label,
            ...(pack.ctas[step] ? { cta: pack.ctas[step] } : {}),
          },
        ]),
      ),
      onboardingUi: pack.ui,
      factoryFirstRun: pack.factory,
    },
  ]),
) as Record<ReviewedLanguage, ReviewedOnboardingLocale>;
